'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var Float32Array = require( '@stdlib/array/float32' );
var Int64Array = require( '@stdlib/array/int64' );
var Number = require( '@stdlib/number/ctor' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var snannsumkbn = tryRequire( resolve( __dirname, './../lib/snannsumkbn.native.js' ) );
var opts = {
	'skip': ( snannsumkbn instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof snannsumkbn, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 5', opts, function test( t ) {
	t.strictEqual( snannsumkbn.length, 5, 'returns expected value' );
	t.end();
});

tape( 'the function calculates the sum of strided array elements (ignoring NaN values) and returns the number of non-NaN elements', opts, function test( t ) {
	var expectedSum;
	var expectedN;
	var count;
	var sum;
	var x;
	var v;

	x = new Float32Array( [ 1.0, -2.0, -4.0, 5.0, 0.0, NaN, 3.0, 0.0, -3.0, 3.0, NaN ] ); // eslint-disable-line max-len

	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );
	v = snannsumkbn( x.length, x, 1, sum, count );

	expectedSum = new Float32Array( [ 3.0 ] );
	expectedN = 9;
	t.strictEqual( v, sum, 'returns expected value' );
	t.deepEqual( sum, expectedSum, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), expectedN, 'returns expected count' );

	x = new Float32Array( [ 1.0, -2.0, -4.0, NaN, 5.0, 0.0, 3.0, NaN ] );

	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );
	v = snannsumkbn( x.length, x, 1, sum, count );

	expectedSum = new Float32Array( [ 3.0 ] );
	expectedN = 6;
	t.strictEqual( v, sum, 'returns expected value' );
	t.deepEqual( sum, expectedSum, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), expectedN, 'returns expected count' );

	x = new Float32Array( [ -4.0, NaN, -4.0 ] );

	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );
	v = snannsumkbn( x.length, x, 1, sum, count );

	expectedSum = new Float32Array( [ -8.0 ] );
	expectedN = 2;
	t.strictEqual( v, sum, 'returns expected value' );
	t.deepEqual( sum, expectedSum, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), expectedN, 'returns expected count' );

	x = new Float32Array( [ NaN, 4.0 ] );

	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );
	v = snannsumkbn( x.length, x, 1, sum, count );

	expectedSum = new Float32Array( [ 4.0 ] );
	expectedN = 1;
	t.strictEqual( v, sum, 'returns expected value' );
	t.deepEqual( sum, expectedSum, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), expectedN, 'returns expected count' );

	x = new Float32Array( [ NaN, NaN ] );

	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );
	v = snannsumkbn( x.length, x, 1, sum, count );

	t.strictEqual( v, sum, 'returns expected value' );
	t.strictEqual( sum[ 0 ], 0.0, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), 0, 'returns expected count' );

	x = new Float32Array( [ NaN ] );

	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );
	v = snannsumkbn( x.length, x, 1, sum, count );

	t.strictEqual( v, sum, 'returns expected value' );
	t.strictEqual( sum[ 0 ], 0.0, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), 0, 'returns expected count' );

	x = new Float32Array( [ 4.0 ] );

	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );
	v = snannsumkbn( x.length, x, 1, sum, count );

	expectedSum = new Float32Array( [ 4.0 ] );
	expectedN = 1;
	t.strictEqual( v, sum, 'returns expected value' );
	t.deepEqual( sum, expectedSum, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), expectedN, 'returns expected count' );

	x = new Float32Array( [ 1.0, 1.0e7, 1.0, -1.0e7 ] );

	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );
	v = snannsumkbn( x.length, x, 1, sum, count );

	expectedSum = new Float32Array( [ 2.0 ] );
	expectedN = 4;
	t.strictEqual( v, sum, 'returns expected value' );
	t.deepEqual( sum, expectedSum, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), expectedN, 'returns expected count' );

	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `0`, the function returns a sum equal to `0.0` and a count equal to `0`', opts, function test( t ) {
	var expectedSum;
	var count;
	var sum;
	var x;
	var v;

	x = new Float32Array( [ 1.0, -2.0, -4.0, 5.0, 3.0 ] );

	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );
	v = snannsumkbn( 0, x, 1, sum, count );

	expectedSum = new Float32Array( [ 0.0 ] );
	t.deepEqual( v, expectedSum, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), 0, 'returns expected count' );

	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );
	v = snannsumkbn( -1, x, 1, sum, count );

	t.deepEqual( v, expectedSum, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), 0, 'returns expected count' );

	t.end();
});

tape( 'if provided an `N` parameter equal to `1`, the function returns a sum equal to the first element and a count equal to `1`', opts, function test( t ) {
	var expectedSum;
	var count;
	var sum;
	var x;
	var v;

	x = new Float32Array( [ 1.0, -2.0, -4.0, 5.0, 3.0 ] );

	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );
	v = snannsumkbn( 1, x, 1, sum, count );

	expectedSum = new Float32Array( [ 1.0 ] );
	t.deepEqual( v, expectedSum, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), 1, 'returns expected count' );

	t.end();
});

tape( 'the function supports `stride` parameters', opts, function test( t ) {
	var expectedSum;
	var count;
	var sum;
	var x;
	var v;

	x = new Float32Array([
		1.0,  // 0
		2.0,
		2.0,  // 1
		-7.0,
		-2.0, // 2
		3.0,
		4.0,  // 3
		2.0,
		NaN,  // 4
		NaN
	]);
	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );

	v = snannsumkbn( 5, x, 2, sum, count );

	expectedSum = new Float32Array( [ 5.0 ] );
	t.deepEqual( v, expectedSum, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), 4, 'returns expected count' );

	t.end();
});

tape( 'the function supports negative `stride` parameters', opts, function test( t ) {
	var expectedSum;
	var count;
	var sum;
	var x;
	var v;

	x = new Float32Array([
		NaN,  // 4
		NaN,
		1.0,  // 3
		2.0,
		2.0,  // 2
		-7.0,
		-2.0, // 1
		3.0,
		4.0,  // 0
		2.0
	]);
	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );

	v = snannsumkbn( 5, x, -2, sum, count );

	expectedSum = new Float32Array( [ 5.0 ] );
	t.deepEqual( v, expectedSum, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), 4, 'returns expected count' );

	t.end();
});

tape( 'if provided a `stride` parameter equal to `0`, the function returns a sum of the first element repeated N times', opts, function test( t ) {
	var expectedSum;
	var count;
	var sum;
	var x;
	var v;

	x = new Float32Array( [ 1.0, -2.0, -4.0, 5.0, 3.0 ] );

	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );
	v = snannsumkbn( x.length, x, 0, sum, count );

	expectedSum = new Float32Array( [ 5.0 ] );
	t.deepEqual( v, expectedSum, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), x.length, 'returns expected count' );

	t.end();
});

tape( 'the function supports view offsets', opts, function test( t ) {
	var expectedSum;
	var count;
	var sum;
	var x0;
	var x1;
	var v;

	x0 = new Float32Array([
		2.0,
		1.0,  // 0
		2.0,
		-2.0, // 1
		-2.0,
		2.0,  // 2
		3.0,
		4.0,  // 3
		6.0,
		NaN,  // 4
		NaN
	]);
	x1 = new Float32Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 ); // start at 2nd element

	sum = new Float32Array( 1 );
	count = new Int64Array( 1 );

	v = snannsumkbn( 5, x1, 2, sum, count );

	expectedSum = new Float32Array( [ 5.0 ] );
	t.deepEqual( v, expectedSum, 'returns expected sum' );
	t.strictEqual( Number( count.get( 0 ) ), 4, 'returns expected count' );

	t.end();
});
